//! Installing a managed toolchain, once, safely, and never twice at a time.
//!
//! The sequence is: ask the provider what to install, take the lock for that
//! install directory, check again whether it is already there, download, verify,
//! unpack into a staging directory, promote with one rename, and clean up.
//!
//! The second check — after the lock, before the download — is the part that is
//! easy to leave out and expensive to omit. Two processes that decide to install
//! the same toolchain at the same moment both pass the first check; the lock
//! makes the second one wait, and the re-check makes it discover the first one's
//! work instead of downloading several hundred megabytes to overwrite it.

use reqwest::Client;

use tinyruntime_bus::{Language, ResolvedRuntime, RuntimeSettings};

use crate::error::{Error, Result};
use crate::provider::Provider;
use crate::{archive, download, store};

/// Provision a managed toolchain and return it.
///
/// # Errors
///
/// Returns the download, digest, install, and empty-install variants of
/// [`Error`] as each stage can fail.
pub(super) async fn run(
    client: &Client,
    language: &Language,
    settings: &RuntimeSettings,
    provider: &dyn Provider,
) -> Result<ResolvedRuntime> {
    let distribution = provider.select_distribution(settings).await?;
    let root = store::cache_root(settings.cache_dir(), language);
    store::ensure_root(&root).await?;

    let install_dir = root.join(&distribution.install_dir_name);
    let _lock = store::InstallLock::acquire(&install_dir, language).await?;

    let install_path = install_dir.to_string_lossy().into_owned();
    if let Some(layout) = provider.layout(&install_path, settings).await? {
        tracing::info!(
            language = language.as_str(),
            version = %layout.version,
            "[tinyruntime::resolve] another install finished this toolchain while we waited"
        );
        return Ok(super::managed(language, &install_dir, layout));
    }

    tracing::info!(
        language = language.as_str(),
        version = %distribution.version,
        "[tinyruntime::resolve] installing a managed toolchain"
    );

    let archive_path = root.join(&distribution.archive_name);
    download::fetch(client, &distribution, &archive_path, language).await?;

    let staging = store::staging_dir(&root);
    store::discard(&staging).await;

    let unpacked =
        match archive::extract(&archive_path, &staging, distribution.format, language).await {
            Ok(unpacked) => unpacked,
            Err(error) => {
                store::discard(&staging).await;
                remove_archive(&archive_path).await;
                return Err(error);
            }
        };

    let promoted = store::promote(&unpacked, &install_dir, language).await;
    store::discard(&staging).await;
    remove_archive(&archive_path).await;
    promoted?;

    provider
        .layout(&install_path, settings)
        .await?
        .map(|layout| super::managed(language, &install_dir, layout))
        .ok_or_else(|| Error::EmptyInstall(language.clone()))
}

/// Drop the archive once it has been unpacked.
///
/// Kept until this point rather than streamed straight into the extractor so a
/// failed unpack can be diagnosed against the bytes that caused it, and removed
/// afterwards because a verified archive is several hundred megabytes of no
/// further use.
async fn remove_archive(path: &std::path::Path) {
    if let Err(error) = tokio::fs::remove_file(path).await
        && error.kind() != std::io::ErrorKind::NotFound
    {
        tracing::debug!("[tinyruntime::resolve] the archive could not be removed: {error}");
    }
}

//! Unit tests for the worker harness payload.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{WORKER_PROTOCOL_VERSION, WorkerHarness};

#[test]
fn a_new_harness_announces_the_compiled_in_protocol() {
    let harness = WorkerHarness::new("pool_worker.py", "# ...", "python");
    assert_eq!(harness.protocol_version, WORKER_PROTOCOL_VERSION);
    assert!(harness.args_before_script.is_empty());
}

#[test]
fn command_args_puts_flags_before_the_script_and_extras_after() {
    let mut harness = WorkerHarness::new("pool_worker.js", "// ...", "node")
        .with_flag("--experimental-vm-modules")
        .with_flag("--experimental-import-meta-resolve");
    harness.args_after_script.push("--serve".to_string());

    assert_eq!(
        harness.command_args("/cache/pool_worker.js"),
        vec![
            "--experimental-vm-modules".to_string(),
            "--experimental-import-meta-resolve".to_string(),
            "/cache/pool_worker.js".to_string(),
            "--serve".to_string(),
        ]
    );
}

#[test]
fn extra_environment_rides_along_with_the_harness() {
    let harness =
        WorkerHarness::new("pool_worker.py", "# ...", "python").with_env("PYTHONUNBUFFERED", "1");
    assert_eq!(
        harness.env,
        vec![("PYTHONUNBUFFERED".to_string(), "1".to_string())]
    );
}

#[test]
fn round_trips_across_the_wire() {
    let harness = WorkerHarness::new("pool_worker.js", "// harness", "node").with_flag("--flag");
    let value = serde_json::to_value(&harness).expect("harness serialises");
    let decoded: WorkerHarness = serde_json::from_value(value).expect("harness round-trips");
    assert_eq!(decoded, harness);
}

//! Unit tests for the contract version bind rule.

use super::{CONTRACT_VERSION, binds, is_compatible};

#[test]
fn a_peer_on_the_same_version_binds() {
    assert!(binds((1, 2), (1, 2)));
    assert!(is_compatible(CONTRACT_VERSION));
}

#[test]
fn a_newer_minor_binds_because_it_still_serves_every_member() {
    assert!(binds((1, 2), (1, 7)));
}

#[test]
fn an_older_minor_does_not_bind() {
    assert!(
        !binds((1, 2), (1, 1)),
        "a caller cannot use a member the other side does not serve"
    );
}

#[test]
fn a_different_major_never_binds() {
    assert!(!binds((1, 0), (2, 0)));
    assert!(!binds((1, 0), (0, 9)));
    assert!(!binds((2, 0), (1, 9)));
}

//! Unit tests for the blocking-pool wrapper.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyruntime_bus::Language;

use super::run;
use crate::error::Error;

#[tokio::test]
async fn a_value_comes_back_from_the_blocking_pool() {
    let value = run(&Language::nodejs(), || Ok(41 + 1))
        .await
        .expect("the work completes");
    assert_eq!(value, 42);
}

#[tokio::test]
async fn a_failure_from_the_work_is_returned_unchanged() {
    // The wrapper must not reclassify what the work already decided.
    let error = run(&Language::nodejs(), || {
        Err::<(), _>(Error::EmptyInstall(Language::nodejs()))
    })
    .await
    .expect_err("the work failed");
    assert!(matches!(error, Error::EmptyInstall(_)), "got {error:?}");
}

#[tokio::test]
async fn a_panicking_task_is_reported_rather_than_propagated() {
    // The only way to reach the join-failure arm, and the reason this wrapper
    // exists in one place instead of once per call site. A panic in a module
    // loaded into someone's process should surface as an error, not unwind
    // through whichever task happened to be awaiting it.
    let error = run(&Language::python(), || -> crate::Result<()> {
        panic!("the blocking work panicked")
    })
    .await
    .expect_err("a panicking task cannot succeed");

    let Error::Install { language, reason } = &error else {
        panic!("got {error:?}");
    };
    assert_eq!(language, &Language::python());
    assert!(reason.contains("did not finish"), "got `{reason}`");
}

//! Unit tests for the language identifier.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{Language, NODEJS, PYTHON};

#[test]
fn normalises_case_and_surrounding_whitespace() {
    assert_eq!(Language::new("  NodeJS \n").as_str(), NODEJS);
    assert_eq!(Language::new("PYTHON").as_str(), PYTHON);
}

#[test]
fn constructors_match_the_published_identifiers() {
    assert_eq!(Language::nodejs().as_str(), NODEJS);
    assert_eq!(Language::python().as_str(), PYTHON);
}

#[test]
fn an_absent_language_is_empty_rather_than_defaulted() {
    assert!(Language::new("   ").is_empty());
    assert!(!Language::nodejs().is_empty());
}

#[test]
fn serialises_as_a_bare_string() {
    let encoded = serde_json::to_value(Language::python()).expect("language serialises");
    assert_eq!(encoded, serde_json::json!("python"));

    let decoded: Language = serde_json::from_value(serde_json::json!("NodeJS"))
        .expect("a language decodes from a bare string");
    assert_eq!(decoded, Language::nodejs());
}

#[test]
fn displays_as_its_identifier() {
    assert_eq!(Language::nodejs().to_string(), "nodejs");
}

#[test]
fn decoding_normalises_the_same_way_the_constructor_does() {
    // Not a restatement of the constructor test: a derived transparent decode
    // would skip normalisation entirely and route a valid request nowhere.
    let decoded: Language =
        serde_json::from_value(serde_json::json!("  PYTHON  ")).expect("language decodes");
    assert_eq!(decoded, Language::python());
    assert_eq!(decoded.as_str(), "python");
}

#[test]
fn a_language_can_be_built_from_either_string_type() {
    assert_eq!(Language::from("NodeJS"), Language::nodejs());
    assert_eq!(Language::from(String::from(" PYTHON ")), Language::python());
}

#[test]
fn ordering_is_by_identifier_so_a_listing_is_stable() {
    let mut languages = vec![Language::python(), Language::nodejs()];
    languages.sort();
    assert_eq!(languages, vec![Language::nodejs(), Language::python()]);
}

#[test]
fn the_identifier_constants_are_what_the_constructors_produce() {
    assert_eq!(NODEJS, "nodejs");
    assert_eq!(PYTHON, "python");
    assert_eq!(Language::new(NODEJS), Language::nodejs());
}

#[test]
fn an_empty_language_displays_as_nothing_rather_than_a_placeholder() {
    assert_eq!(Language::new("").to_string(), "");
}

//! Unit tests for the resolution payloads.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{ResolveRequest, ResolveResponse, ResolvedRuntime, RuntimeSource};
use crate::{Language, RuntimeLayout, RuntimeSettings};

fn layout() -> RuntimeLayout {
    RuntimeLayout::new("22.11.0", "/cache/node-v22.11.0/bin")
        .with_executable("node", "/cache/node-v22.11.0/bin/node")
}

#[test]
fn a_probe_forbids_installing() {
    let probe = ResolveRequest::probe(Language::nodejs(), RuntimeSettings::new("v22.11.0"));
    assert!(!probe.install);
    let resolve = ResolveRequest::new(Language::nodejs(), RuntimeSettings::new("v22.11.0"));
    assert!(resolve.install);
}

#[test]
fn a_resolution_carries_the_layout_it_was_built_from() {
    let runtime =
        ResolvedRuntime::from_layout(Language::nodejs(), RuntimeSource::Managed, layout());
    assert_eq!(runtime.version, "22.11.0");
    assert_eq!(
        runtime.executable("node"),
        Some("/cache/node-v22.11.0/bin/node")
    );
    assert_eq!(
        runtime.install_dir, None,
        "the directory is recorded separately"
    );
}

#[test]
fn a_system_resolution_has_no_install_directory() {
    let runtime = ResolvedRuntime::from_layout(Language::nodejs(), RuntimeSource::System, layout());
    assert_eq!(runtime.source, RuntimeSource::System);
    assert!(runtime.install_dir.is_none());
}

#[test]
fn nothing_provisioned_is_a_successful_empty_answer() {
    assert_eq!(ResolveResponse::missing().runtime, None);
    let runtime = ResolvedRuntime::from_layout(Language::python(), RuntimeSource::System, layout());
    assert!(ResolveResponse::found(runtime).runtime.is_some());
}

#[test]
fn the_source_wire_form_is_pinned() {
    let value = serde_json::to_value(RuntimeSource::Managed).expect("source serialises");
    assert_eq!(value, serde_json::json!("managed"));
    assert_eq!(
        serde_json::to_value(RuntimeSource::System).expect("source serialises"),
        serde_json::json!("system")
    );
}

//! Unit tests for the per-language settings payload.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::RuntimeSettings;

#[test]
fn new_enables_the_language_and_prefers_the_host_interpreter() {
    let settings = RuntimeSettings::new("v22.11.0");
    assert!(settings.enabled);
    assert!(settings.prefer_system);
    assert_eq!(settings.version, "v22.11.0");
}

#[test]
fn blank_optional_fields_read_as_absent() {
    let mut settings = RuntimeSettings::new("3.12");
    assert_eq!(settings.cache_dir(), None);
    assert_eq!(settings.release_tag(), None);
    assert_eq!(settings.preferred_command(), None);
    assert_eq!(settings.maximum_version(), None);

    settings.cache_dir = "   ".to_string();
    assert_eq!(settings.cache_dir(), None, "whitespace is still absent");
}

#[test]
fn set_optional_fields_are_trimmed() {
    let mut settings = RuntimeSettings::new("3.12");
    settings.preferred_command = "  /usr/bin/python3.12  ".to_string();
    assert_eq!(settings.preferred_command(), Some("/usr/bin/python3.12"));
}

#[test]
fn pins_its_wire_representation() {
    let value = serde_json::to_value(RuntimeSettings::new("3.12")).expect("settings serialise");
    assert_eq!(
        value,
        serde_json::json!({
            "enabled": true,
            "prefer_system": true,
            "version": "3.12",
            "maximum_version": "",
            "cache_dir": "",
            "release_tag": "",
            "preferred_command": "",
        })
    );
}

//! Unit tests for the module configuration.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyruntime_bus::{Language, names};

use super::{ModuleConfig, ProviderRoute};

#[test]
fn the_default_routes_the_first_party_providers() {
    let config = ModuleConfig::default();
    assert_eq!(config.providers.len(), 2);
    assert_eq!(config.providers[0].language, Language::nodejs());
    assert_eq!(config.providers[0].bus_name, names::providers::NODEJS);
    assert_eq!(config.providers[1].language, Language::python());
}

#[test]
fn an_empty_configuration_object_still_yields_the_defaults() {
    // A host that supplies `{}` means "the usual", not "route nothing".
    let config: ModuleConfig = serde_json::from_value(serde_json::json!({})).unwrap();
    assert_eq!(config, ModuleConfig::default());
}

#[test]
fn a_host_can_route_a_language_somewhere_else() {
    let config: ModuleConfig = serde_json::from_value(serde_json::json!({
        "providers": [{ "language": "nodejs", "bus_name": "ai.example.MyNode" }]
    }))
    .unwrap();
    assert_eq!(
        config.providers,
        vec![ProviderRoute::new(Language::nodejs(), "ai.example.MyNode")]
    );
}

#[test]
fn a_host_can_route_a_language_this_build_never_heard_of() {
    // The point of configuring routes rather than compiling them in: a new
    // provider module must not require a new router build.
    let config: ModuleConfig = serde_json::from_value(serde_json::json!({
        "providers": [{ "language": "ruby", "bus_name": "ai.example.Ruby" }]
    }))
    .unwrap();
    assert_eq!(config.providers[0].language, Language::new("ruby"));
}

#[test]
fn an_explicit_harness_directory_is_honoured() {
    let config = ModuleConfig {
        harness_dir: "/var/lib/tinyruntime".to_string(),
        ..ModuleConfig::default()
    };
    assert_eq!(
        config.harness_root(),
        std::path::Path::new("/var/lib/tinyruntime")
    );
}

#[test]
fn the_default_harness_directory_is_under_a_cache() {
    let root = ModuleConfig::default().harness_root();
    assert!(root.ends_with("harnesses"), "got {}", root.display());
}
